/**
 * Interpolate actual value into selector template.
 *
 * This function has counterpart in PHP: `ModuleElementsUtils::interpolate_selector()`.
 *
 * @since ??
 *
 * @param {object} params Function params.
 * @param {string} params.value Actual value to interpolate.
 * @param {object|string} params.selectorTemplate Selector template.
 * @param {string} params.placeholder Optional. Placeholder to replace with actual value. Default is `{{selector}}`.
 *
 * @returns {object|string} Interpolated selector template.
 * If the selector template is a string, a string is returned.
 * Otherwise an array is returned.
 */
export declare const interpolateSelector: <TSelectorTemplate>({ value, selectorTemplate, placeholder, }: {
    value: string;
    selectorTemplate: TSelectorTemplate;
    placeholder?: string;
}) => TSelectorTemplate;
